"use strict";

// Ghost, the spoken word game (en.wikipedia.org/wiki/Ghost_(game)), for 2 to 6 players.
// Players take turns adding a letter to a shared fragment, which must be the beginning of a real
// word. Instead of adding a letter, a player may challenge the previous player to name a word that
// starts with the fragment: if they can, the challenger loses the round; if not, they lose it.
// Whoever completes a word of 4 or more letters loses the round. Each round lost earns a letter of
// G-H-O-S-T; with all five a player is out. The last player left wins.
// Choices where the page is silent: words come from the built-in English list below (4+ letters,
// common words); a completed word is always noticed; the player to the left of the previous round's
// first player starts each new round (skipping players who are out).
//
// Word list: SCOWL (sizes 10, 20 and 35, English and American), http://wordlist.aspell.net/
// Copyright 2000-2018 by Kevin Atkinson. Permission to use, copy, modify, distribute and sell these
// word lists, the associated scripts, the output created from the scripts, and its documentation
// for any purpose is hereby granted without fee, provided that the above copyright notice appears in
// all copies and that both that copyright notice and this permission notice appear in supporting
// documentation. Kevin Atkinson makes no representations about the suitability of this array for
// any purpose. It is provided "as is" without express or implied warranty.
// Encoding (see wordlist.py): sorted words, each written as a digit (letters shared with the
// previous word, at most 9) followed by the rest of the word.

const MIN_WORD = 4;
const GHOST = "GHOST";
const WORDS_CODED = "";

let WORDS = null;
function words() {
  if (WORDS) return WORDS;
  const list = [];
  let prev = "";
  let i = 0;
  while (i < WORDS_CODED.length) {
    const keep = WORDS_CODED.charCodeAt(i) - 48;
    let j = i + 1;
    while (j < WORDS_CODED.length) {
      const c = WORDS_CODED.charCodeAt(j);
      if (c >= 48 && c <= 57) break;
      j++;
    }
    prev = prev.slice(0, keep) + WORDS_CODED.slice(i + 1, j);
    list.push(prev);
    i = j;
  }
  WORDS = list;
  return list;
}

/** Index of the first word >= [s] (binary search). */
function lowerBound(s) {
  const list = words();
  let lo = 0, hi = list.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (list[mid] < s) lo = mid + 1; else hi = mid;
  }
  return lo;
}
const isWord = (s) => { const i = lowerBound(s); return i < words().length && words()[i] === s; };
const isPrefix = (s) => { const i = lowerBound(s); return i < words().length && words()[i].startsWith(s); };
/** A word that starts with [s] and is longer than it (for the computer's answers), or null. */
function longerWordWith(s) {
  const list = words();
  for (let i = lowerBound(s); i < list.length && list[i].startsWith(s); i++) if (list[i].length > s.length) return list[i];
  return null;
}

const active = (state) => state.letters.map((n, s) => (n < GHOST.length ? s : -1)).filter((s) => s >= 0);

function nextActive(state, seat) {
  const n = state.letters.length;
  for (let k = 1; k <= n; k++) {
    const s = (seat + k) % n;
    if (state.letters[s] < GHOST.length) return s;
  }
  return seat;
}

/** [loser] takes a letter; then a new round starts, or the game ends. */
function loseRound(state, loser, reason, word) {
  const letters = state.letters.map((n, s) => (s === loser ? n + 1 : n));
  const last = { loser, reason, fragment: state.fragment, word: word || null };
  const next = { ...state, letters, last, challenge: null };
  const left = active(next);
  if (left.length === 1) return { ...next, winner: left[0], fragment: "", to_move: left[0] };
  const starter = nextActive(next, state.starter);
  return { ...next, fragment: "", starter, to_move: starter, last_adder: null, round: state.round + 1 };
}

function apply(state, seat, move) {
  if (state.winner !== null) throw new InvalidMove("the game is over");
  if (seat !== state.to_move) throw new InvalidMove("it is not your turn");
  if (state.challenge) {
    // The challenged player answers with a word, or gives up.
    if ("word" in move) {
      const word = move.word.toLowerCase();
      if (word.startsWith(state.fragment) && word.length > state.fragment.length && isWord(word)) {
        return loseRound(state, state.challenge.by, "challenge_failed", word);
      }
      return loseRound(state, seat, "bad_word", word);
    }
    if ("give_up" in move) return loseRound(state, seat, "gave_up");
    throw new InvalidMove("answer the challenge with a word, or give up");
  }
  if ("challenge" in move) {
    if (!state.fragment) throw new InvalidMove("there is nothing to challenge yet");
    const target = state.last_adder;
    return { ...state, challenge: { by: seat, target }, to_move: target };
  }
  if ("letter" in move) {
    const fragment = state.fragment + move.letter.toLowerCase();
    const next = { ...state, fragment, last_adder: seat, last: null };
    if (fragment.length >= MIN_WORD && isWord(fragment)) return loseRound(next, seat, "completed", fragment);
    return { ...next, to_move: nextActive(state, seat) };
  }
  throw new InvalidMove("add a letter or challenge");
}

function validateMove(move) {
  const keys = move && typeof move === "object" && !Array.isArray(move) ? Object.keys(move) : [];
  const ok = keys.length === 1 && (
    (keys[0] === "letter" && typeof move.letter === "string" && /^[a-zA-Z]$/.test(move.letter)) ||
    (keys[0] === "word" && typeof move.word === "string" && /^[a-zA-Z]{1,30}$/.test(move.word)) ||
    (keys[0] === "challenge" && move.challenge === true) ||
    (keys[0] === "give_up" && move.give_up === true));
  if (!ok) throw new InvalidMove("send a letter, a challenge, a word or give up");
}

const seatOf = (ctx, playerId) => ctx.players.findIndex((p) => p.id === playerId);

function payouts(winner, ctx) {
  const humans = ctx.players.filter((p) => p.kind === "human");
  if (!humans.length) return {};
  const out = Object.fromEntries(humans.map((h) => [h.id, 0]));
  const champ = ctx.players[winner];
  if (champ.kind === "human") { out[champ.id] = ctx.pot; return out; }
  const share = Math.floor(ctx.pot / humans.length);
  humans.forEach((h, i) => { out[h.id] = share + (i < ctx.pot - share * humans.length ? 1 : 0); });
  return out;
}

const ALPHABET = "abcdefghijklmnopqrstuvwxyz";

/** Letters that keep the fragment a real beginning without completing a word. */
function safeLetters(fragment) {
  return [...ALPHABET].filter((c) => {
    const f = fragment + c;
    return isPrefix(f) && !(f.length >= MIN_WORD && isWord(f)) && longerWordWith(f) !== null;
  });
}

function chooseMove(state, seat, rng) {
  if (state.challenge) {
    const word = longerWordWith(state.fragment);
    return word ? { word } : { give_up: true };
  }
  if (state.fragment && !isPrefix(state.fragment)) return { challenge: true };
  const safe = safeLetters(state.fragment);
  if (safe.length) return { letter: safe[Math.floor(rng() * safe.length)] };
  // Every letter completes a word or leads nowhere: bluff with any letter that is still a beginning.
  const any = [...ALPHABET].filter((c) => isPrefix(state.fragment + c));
  if (state.fragment && !any.length) return { challenge: true };
  return { letter: (any.length ? any : [...ALPHABET])[Math.floor(rng() * (any.length || 26))] };
}

const game = {
  newMatch(ctx) {
    const n = ctx.players.length;
    const state = { letters: Array(n).fill(0), fragment: "", to_move: 0, starter: 0, last_adder: null,
                    challenge: null, last: null, round: 1, winner: null };
    return { state, turn: [ctx.players[0].id] };
  },

  applyMove(state, playerId, move, ctx) {
    validateMove(move);
    const next = apply(state, seatOf(ctx, playerId), move);
    if (next.winner !== null) return { state: next, turn: null, payouts: payouts(next.winner, ctx) };
    return { state: next, turn: [ctx.players[next.to_move].id] };
  },

  computerMove(state, playerId, ctx) { return chooseMove(state, seatOf(ctx, playerId), () => ctx.random()); },

  randomMove(state, playerId, ctx) {
    if (state.challenge) {
      const word = longerWordWith(state.fragment);
      return ctx.random() < 0.7 && word ? { word } : { give_up: true };
    }
    if (state.fragment && ctx.random() < 0.15) return { challenge: true };
    return { letter: ALPHABET[Math.floor(ctx.random() * 26)] };
  },

  viewFor(state, playerId, ctx) {
    const seat = playerId === null ? -1 : seatOf(ctx, playerId);
    return {
      letters: state.letters, fragment: state.fragment, to_move: state.to_move, last_adder: state.last_adder,
      challenge: state.challenge, last: state.last, round: state.round, winner: state.winner,
      my_seat: seat >= 0 ? seat : null,
    };
  },
};
